        for j in range(i + 1, N):
            if is_prime[nums[i] + nums[j]]:
                q.put([nums[i] + nums[j], i, j])


    UF = UnionFinder(N)

    while not q.empty():
        val, u, v = q.get()
        # print(UF.parent)
